    spTierNone: 'Geen badge',
    feeTierTitle: 'Vergoedingsniveausysteem',
    feeTierSubtitle: 'Kostenvermindering op basis van badges',
    feeTierDesc: 'Onze revolutionaire kostenstructuur beloont DeHub-tokenhouders met aanzienlijk lagere platformkosten. Vanaf een standaardvergoeding van 10% verlaagt elk badge-niveau dat wordt verdiend met verhoogde tokenholdings de kosten met 0,69% en bereikt uiteindelijk slechts 1% voor Megalodon-badgehouders - een verlaging van 99% voor onze meest toegewijde communityleden.',
    platformFeeStructure: 'Platformkostenstructuur',
    fee: 'vergoeding',
    feeCalcBenefits: 'Kostenberekeningsvoordelen',
